  const normalized = text(value, label, 64);
  const timestamp = Date.parse(normalized);
  if (!Number.isFinite(timestamp) ||
      new Date(timestamp).toISOString() !== normalized) {
    fail(label + " must be canonical ISO-8601");
  }
